entries.content:
{
  "setting_title": "行尸设定集",
  "origin_story": {
    "summary": "行尸的根源并非传统意义上的瘟疫或诅咒，而是一场宇宙级的物理法则异变。",
    "mechanism": "一次不明的、影响深远的宇宙事件，导致分隔“阳界”（我们所处的世界）与“阴界”（一个充满死寂、恒定能量的维度）的“现实帷幕”在全球范围内变薄、破损。",
    "result": "来自阴界的能量（下称“阴能”）渗透而出，附着并驱动死者的躯体，创造出了“行尸”这种违背阳界生命法则的存在。"
  },
  "chapters": [
    {
      "chapter_number": 1,
      "chapter_title": "根本性质 - “阴界”的傀儡",
      "sections": [
        {
          "title": "本质",
          "content": "行尸是彻底死亡的物理躯壳，被来自另一维度的“阴能”所灌注并操控的傀儡。它们不再是生物，而是一种遵循全新物理法则的“异物”。"
        },
        {
          "title": "寿命：不朽",
          "mechanism": "“阴能”的本质是“静止”与“恒定”，是生命活力（熵增、变化、腐败）的对立面。当它占据一具尸体时，阳界的一切腐败过程都会被强行中止。",
          "conclusion": "行尸不会自然腐烂，其躯体被完美地“冻结”在转化完成的那一刻。除非被外力彻底摧毁，否则它们的寿命是永恒的。"
        },
        {
          "title": "能量来源：无穷",
          "content": "行尸不知疲倦，其活动能量并非来自消耗自身，而是由“现实帷幕”的裂隙中持续渗漏的“阴能”所直接提供。它们是连接着另一个维度能源的终端，因此拥有近乎无限的动力。"
        }
      ]
    },
    {
      "chapter_number": 2,
      "chapter_title": "核心法则 - 阴阳相克",
      "introduction": "行尸的一切行为模式，都源于其体内的“阴能”与我们“阳界”法则的相互作用。",
      "sections": [
        {
          "title": "核心弱点 I：阳光抑制",
          "mechanism": "太阳是阳界最纯粹、最强大的“阳能”来源。当无遮挡的阳光直射在行尸身上时，高浓度的“阳能”会与“阴能”发生剧烈的中和反应，暂时性地切断“阴能”对躯体的控制，导致其陷入完全麻痹的静止状态。",
          "derived_rule": "阴影、云层、雨雪、黄昏和夜晚，都能大幅削弱阳光的“纯度”，使得“阴能”可以重新主导躯体，让行尸恢复活动能力。"
        },
        {
          "title": "核心弱点 II：头部要害",
          "mechanism": "“阴能”并非均匀分布在尸体内，而是以头部（原大脑和脑干位置）为核心节点，构建起一个控制全身的能量网络。彻底摧毁这个核心节点，是唯一能让能量网络永久崩溃、使行尸彻底“死亡”的方法。"
        },
        {
          "title": "主要感知：生灵感应",
          "mechanism": "这是“阴阳相吸”的法则体现。活物所散发的生命能量（“阳气”、生物电场）对于行尸体内的“阴能”来说，是极其醒目和强烈的“信标”。",
          "manifestation": "行尸能本能地、精准地感知到附近活物的位置，如同磁石被铁吸引。此感应无视黑暗、声音和气味，使得常规躲藏变得毫无意义。"
        }
      ]
    },
    {
      "chapter_number": 3,
      "chapter_title": "分级详述 - 异化的形态",
      "types": [
        {
          "name": "凡尸 (普通行尸)",
          "abilities": {
            "strength": "由“阴能”直接驱动，能爆发出远超人类肌肉限制的蛮力。",
            "speed": "缓慢蹒跚。灌注的“阴能”较为稀薄，只能进行粗略的、非协调性的动作。"
          },
          "role": "构成灾难主体的“步兵”，依靠无穷的数量和耐力淹没一切。"
        },
        {
          "name": "疾尸 (迅猛行尸)",
          "abilities": {
            "explosive_burst": "其体内的“阴能”更浓郁，能进行瞬间的、大量的能量释放，驱动躯体进行短暂的直线高速冲击。这种爆发会暂时性地扰动其能量稳定，因此在冲刺后会有短暂僵直。"
          },
          "role": "致命的刺客，能瞬间突破防线，其动静结合的攻击模式极难防御。"
        },
        {
          "name": "尸王 (首领)",
          "essence": "一个强大的“阴能”汇聚节点，相当于“现实帷幕”上的一个较大的裂口。",
          "abilities": [
            {
              "name": "能量再造（再生）",
              "description": "由于其拥有的“阴能”流量巨大，它甚至可以调用能量来重构被破坏的物质形态。只要头部核心节点无损，其躯干和四肢受到的严重创伤，都能通过能量对物质的重新排序而缓慢愈合。"
            },
            {
              "name": "统御哀嚎（次声波）",
              "description": "它能通过释放一种混合了“阴能”的次声波，与附近其他行尸体内的“阴能”产生共鸣，从而引导和指挥它们的行动。这声“哀嚎”是其作为能量节点的“场”的显性表现。"
            }
          ],
          "role": "尸潮的绝对核心与指挥官。它的存在，意味着无序的灾难变成了有组织的进攻。"
        }
      ]
    }
  ]
}

