              "description": "它能通过释放一种混合了“阴能”的次声波，与附近其他行尸体内的“阴能”产生共鸣，从而引导和指挥它们的行动。这声“哀嚎”是其作为能量节点的“场”的显性表现。"
            }
          ],
          "role": "尸潮的绝对核心与指挥官。它的存在，意味着无序的灾难变成了有组织的进攻。"
        }
      ]
    }
  ]
}

entries.content:
{
  "setting_title": "世界格局设定",
  "world_overview": {
    "origin": {
      "name": "阴界侵蚀 (Yin-World Erosion)",
      "mechanism": "一场原因不明的宇宙事件导致现实维度（阳界）破损，来自充满死寂能量的另一维度（阴界）的能量渗透而出，驱动死者，扭曲生者。",
      "human_perspective": "人类无法理解其本质，将其视为一场颠覆常理的、原因不明的“大灾变”或“恶性瘟疫”。"
    },
    "timeline": "靖康二年春 (Spring, 1127 AD)",
    "current_state": "灾变发生数月后，世界人口锐减80%-90%，进入了人类、行尸、蚀兽三方并存的黑暗时代。"
  },
  "universal_survival_laws": [
    {
      "law": "太阳的二元性",
      "description": "白天不再绝对安全。阳光能抑制“行尸”，但对“蚀兽”无效。人类活动被压缩到视野开阔、光照充足的区域和时段。"
    },
    {
      "law": "堡垒至上原则",
      "description": "防御工事需要同时应对行尸的围攻和蚀兽的强攻，促使幸存者据点进行纵深化、多功能的改造。"
    },
    {
      "law": "海洋的陷落",
      "description": "以“蚀虎鲸群”为首的海洋蚀兽出现，使得大规模、长距离的航海活动变得极为危险，海洋不再是安全的避风港。"
    },
    {
      "law": "资源的双重消耗",
      "description": "幸存者必须为行尸和蚀兽准备两套不同的武器与战术，极大地加剧了铁器等关键资源的消耗。"
    }
  ],
  "major_powers": {
    "southern_song_remnant": {
      "name": "南渡朝廷 - “风雨飘摇的巨舟”",
      "new_hardship": "南方温暖湿润的环境催生了种类繁多的强大蚀兽，如“蚀虎”和“蚀（猪）群”，严重威胁运输线和农业区的安全。",
      "ruler_dynamics": {
        "title": "掌权者动向",
        "description": "赵构朝廷内部“主战派”与“求存派”斗争激烈。为应对蚀兽威胁，被迫成立“巡山猎兽营”，进一步消耗了本已紧张的兵力。同时建立“察事厅”等特务机构，在末世中加强对军队的控制。"
      },
      "commoner_dynamics": {
        "title": "普通人动向",
        "description": "百姓对野外的恐惧达到顶点。除了行尸，“山里的大家伙”也成了新的恐怖传说。生活在“编户著籍”制度下，为换取口粮而从事繁重的劳役。"
      }
    },
    "jurchen_jin_enclaves": {
      "name": "金国“飞地” - “绝境中的饿狼”",
      "new_hardship": "赖以为生的“白日掠夺”战术因“蚀狼群”等蚀兽的出现而风险倍增，骑兵在复杂地形中极易遭到伏击，损失惨重。",
      "ruler_dynamics": {
        "title": "掌权者动向",
        "description": "金军将帅被迫放弃分散掠夺，转而集结重兵发动速战速决的“惩戒式远征”，以求在短时间内肃清一个区域。内部关于“突围”还是“就地建国”的争论更加激烈。"
      },
      "commoner_dynamics": {
        "title": "普通人士兵动向",
        "description": "士气进一步下跌，精神长期处于高压状态。即使在白天，野外也充满了未知的致命威胁。萨满巫师通过更频繁的祭祀来安抚军心。"
      }
    },
    "northern_resistance": {
      "name": "北方抵抗力量 - “被不断敲打的龟壳”",
      "new_hardship": "坞堡的高墙能防尸潮，但难以抵御“蚀熊”或“蚀（猪）群”的持续性物理撞击，外墙被突破的风险大增。",
      "ruler_dynamics": {
        "title": "掌权者（堡主）动向",
        "description": "坞堡的防御工事开始“纵深化改造”，向内挖掘多层壕沟和陷阱区，修建瓮城和街垒，以空间换取反应时间。"
      },
      "commoner_dynamics": {
        "title": "普通人动向",
        "description": "坞堡内的管制更加严苛，人人皆兵。任何可能吸引蚀兽的行为（如处理食物不当留下血腥味）都会受到重罚。"
      }
    },
    "byzantine_empire": {
      "name": "拜占庭帝国 - “光芒渐暗的灯塔”",
      "new_hardship": "“蚀虎鲸群”频繁攻击运粮船队，直接打击了帝国的海上生命线，导致君士坦丁堡首次出现粮食危机，绝对安全的神话被打破。",
      "ruler_dynamics": {
        "title": "掌权者动向",
        "description": "皇帝和幕僚将此视为最严峻的挑战。他们采取了多种应对策略：建立“护航舰队”、研发“深水希腊火”、设立“诱饵航线”等，试图在海战中夺回优势。"
      },
      "commoner_dynamics": {
        "title": "普通人动向",
        "description": "城内首次出现粮食配给削减，引发了部分恐慌。“探索舰队”水手成为最高危的职业，但其带回的外部世界信息，仍然是市民最主要的娱乐和谈资。"
      }
    },
    "european_kingdoms": {
      "name": "欧罗巴诸国 - “信仰的孤岛”",
      "new_hardship": "“蚀狼”与“蚀熊”盘踞在广袤的森林中，使得各个城堡之间的陆路交通近乎断绝，各封建领地真正沦为“孤岛”。",
      "ruler_dynamics": {
        "title": "掌权者动向",
        "description": "教宗与国王试图维持的“神圣同盟”因交通断绝而名存实亡。地方领主的割据状态被彻底固化，他们唯一关心的就是加固自己的城堡和搜刮领地内的资源。"
      },
      "commoner_dynamics": {
        "title": "普通人动向",
        "description": "一个名为“信使”或“跑者”的新职业应运而生。他们是顶级的野外生存专家，负责在各个城堡孤岛间传递信息，其危险性与回报都极高。"
      }
    }
  }
}

