entries.content:
{
  "framework_title": "人物生成框架",
  "sections": [
    {
      "section_number": "2.1",
      "section_title": "基础信息",
      "fields": [
        {
          "field_name": "[姓名]",
          "prompt": "（请根据其所属文化和阶层，生成一个合理的名字。）"
        },
        {
          "field_name": "[性别]",
          "prompt": "（男性 / 女性）"
        },
        {
          "field_name": "[年龄]",
          "prompt": "（请填写具体数字）"
        },
        {
          "field_name": "[所属势力]",
          "prompt": "（请从“南渡朝廷”、“金国飞地”、“北方坞堡”、“欧洲城堡”、“拜占庭远征队”、“伊斯兰幸存者社区”等势力中选择。）"
        },
        {
          "field_name": "[社会阶层/职业]",
          "prompt": "（例如：士兵、难民、工匠、学者、神职人员、贵族、信使、猎兽人等。）"
        }
      ]
    },
    {
      "section_number": "2.2",
      "section_title": "生存状态",
      "fields": [
        {
          "field_name": "[动机与目标]",
          "prompt": "（他/她最核心的驱动力是什么？例如：寻找失散的家人、向某个势力复仇、单纯地活下去、重建文明、保守一个秘密等。）"
        },
        {
          "field_name": "[掌握的技能]",
          "prompt": "（请列举1-3个在末世中极为有用的技能。例如：冶炼和锻造、草药辨识与制药、高超的射术、读写与计算能力、野外陷阱布置、城防工事修筑等。）"
        },
        {
          "field_name": "[持有的关键物品]",
          "prompt": "（他/她有什么标志性的、或对其生存至关重要的物品？可参考“物品生成框架”。）"
        }
      ]
    },
    {
      "section_number": "2.3",
      "section_title": "文化烙印",
      "fields": [
        {
          "field_name": "[世界观/信仰]",
          "prompt": "（他/她如何理解这场灾难？是一个宋人儒生眼中的“礼崩乐坏，天道失常”，还是一个欧洲修士眼中的“上帝的最终审判”？）"
        },
        {
          "field_name": "[日常习俗]",
          "prompt": "（描述一个能体现其背景的、微小但生动的日常习惯。例如：南宋士兵在饭前会用指尖蘸水在桌上画一个太阳；拜占庭学者在阅读前会用酒精擦拭双手等。）"
        }
      ]
    }
  ]
}

