entries.content:
{
  "framework_title": "事件生成框架",
  "sections": [
    {
      "section_number": "3.1",
      "section_title": "事件类型",
      "fields": [
        {
          "field_name": "[类型]",
          "prompt": "（请从以下类型中选择：资源搜集、据点防御战、蚀兽狩猎、政治密谋、派系冲突、探索任务、内部审判等。）"
        }
      ]
    },
    {
      "section_number": "3.2",
      "section_title": "关键参数",
      "fields": [
        {
          "field_name": "[发生地点]",
          "prompt": "（例如：一座废弃城市的盐仓、一段被尸群围困的城墙、领主城堡的议事厅、危机四伏的森林驿道等。）"
        },
        {
          "field_name": "[参与方]",
          "prompt": "（例如：一支“逐光队” vs. 一头“蚀虎”；一个坞堡的民兵 vs. 另一伙来抢水的幸存者；一个拜占庭信使试图穿越金军控制区等。）"
        },
        {
          "field_name": "[核心目标]",
          "prompt": "（例如：夺取一批珍贵的铁器、刺杀敌对势力的首领、护送重要人物或情报、寻找传说中的安全区等。）"
        }
      ]
    },
    {
      "section_number": "3.3",
      "section_title": "环境变数（重要）",
      "fields": [
        {
          "field_name": "[发生时间]",
          "prompt": "（是行尸静止的正午，还是蚀兽活跃的白天？是行尸狂暴的夜晚，还是危机四伏的黄昏？）"
        },
        {
          "field_name": "[天气状况]",
          "prompt": "（是晴朗无云（对人类有利），还是阴天/雨雪（对人类极为不利）？）"
        },
        {
          "field_name": "[威胁组合]",
          "prompt": "（事件中存在何种威胁？是仅有行尸？仅有蚀兽？还是行尸与蚀兽同时出现？亦或是人类之间的冲突？）"
        }
      ]
    }
  ]
}

