entries.content:
{
  "setting_title": "浩劫后十年（约 1135 AD）",
  "chapters": [
    {
      "chapter_number": 1,
      "chapter_title": "新的社会阶层与结构",
      "introduction": "在旧有的“士农工商”体系彻底崩溃后，一个基于“生存价值”的、更加残酷和实用主义的新社会阶层结构在全球幸存者中形成。",
      "social_classes": [
        {
          "class_name": "“奔行者”阶层 (The Runners)",
          "class_subtitle": "神经与血脉",
          "composition": "由最顶尖的斥候、信使、探险家和商人组成。在我们的设定中，他们被称为“斥候”（宋）、“奔马邮”（金）、“信使” (Runners)（欧罗巴）。",
          "social_role": "他们是连接各个幸存者“孤岛”的神经网络和循环系统。他们传递着至关重要的情报、稀有的物资、以及维系文明联系的信件。他们绘制着这个面目全非的世界的地图，标记着尸潮的动向、蚀兽的巢穴和安全的“白日通道”。",
          "social_status": "极度崇高且备受敬畏。他们享受着最好的食物、武器和住所，并拥有在不同据点间相对自由通行的特权。他们通常组成小型的、纪律严明的“公会”或“行帮”，内部有秘密的暗号和路线图，外人难以加入。成为一名“奔行者”，是许多末世青年最向往的、也是最危险的梦想。"
        },
        {
          "class_name": "“持械者”阶层 (The Arms-Bearers)",
          "class_subtitle": "骨骼与利爪",
          "composition": "所有职业军人和专职的战斗人员。",
          "subdivisions": [
            {
              "name": "“守备军”",
              "description": "负责保卫据点，是数量最多的武装力量。他们的地位高于普通平民，但生活同样艰苦。"
            },
            {
              "name": "“净化者”",
              "description": "这是新诞生的精英战斗阶层。在南宋，他们是“荡寇司”下属的“斩尸营”；在欧洲，他们是“圣殿骑士团”重组后的“驱魔骑士团”。他们的任务不是防守，而是主动出击，猎杀“尸王”和强大的“蚀兽”，清除关键道路上的威胁。"
            }
          ],
          "social_status": "“净化者”是这个时代的英雄和明星。他们的事迹被谱写成歌曲传唱。他们通常沉默寡言、遍体鳞伤，身上佩戴着用“蚀兽”牙齿或骨板制成的战利品作为勋章，这既是荣誉，也是一种精神上的护身符。"
        },
        {
          "class_name": "“智识者”阶层 (The Knowledge Keepers)",
          "class_subtitle": "大脑与记忆",
          "composition": "掌握着旧世界知识和关键技术的学者、工匠与医生。",
          "subdivisions": [
            {
              "name": "工匠（铁匠、木匠）",
              "description": "地位空前提高，一个能打造精良武器和维修城防器械的铁匠，其价值堪比一名百夫长。"
            },
            {
              "name": "医生/药师",
              "description": "他们无法治愈尸毒，但他们懂得如何处理外伤、接骨、以及利用草药防治“凋零之瘴”引发的普通疾病。"
            },
            {
              "name": "学者（工程师、天文学家）",
              "description": "他们是“国宝”级的存在，被严密地保护起来。他们负责改良武器、设计更坚固的防御工事、以及通过观测天象来预测天气——这在依赖太阳的末世中至关重要。"
            }
          ],
          "social_status": "他们如同被豢养在黄金鸟笼中的金丝雀，生活最优渥，但几乎没有人身自由。他们的知识被所属势力视为最高机密。"
        },
        {
          "class_name": "“生产者”阶层 (The Producers)",
          "class_subtitle": "血肉与根基",
          "composition": "农民、普通手工业者、以及所有从事基础生产的平民。",
          "social_status": "他们是整个幸存者金字塔的基石，数量最多，地位最低。他们用最繁重的劳动，换取最基础的生存保障。他们的生命脆弱，但他们的存在，决定了一个据点能延续多久。"
        }
      ]
    }

